const menu=document.querySelector('#menu');menu?.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));document.querySelector('#navigation').classList.toggle('open',open)});document.querySelectorAll('[data-filter]').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));let count=0;document.querySelectorAll('[data-category]').forEach(card=>{card.hidden=button.dataset.filter!=='All'&&card.dataset.category!==button.dataset.filter;if(!card.hidden)count++});document.querySelector('#results').textContent=count+' projects'}));document.querySelector('#year').textContent=new Date().getFullYear();if(matchMedia('(pointer:fine) and (prefers-reduced-motion:no-preference)').matches){const scene=document.querySelector('.reference-scene'),card=document.querySelector('.tilt');scene?.addEventListener('pointermove',e=>{const r=scene.getBoundingClientRect();card.style.transform=`rotateY(${(e.clientX-r.left)/r.width*20-18}deg) rotateX(${12-(e.clientY-r.top)/r.height*15}deg) rotateZ(-3deg)`});scene?.addEventListener('pointerleave',()=>card.style.transform='');}
// Accessible, browser-local UI samples. User input is rendered with textContent.
document.querySelectorAll('.ui-demo').forEach(demo=>{
 const seed=()=>[{id:1,name:'Contact form',type:'Form',status:'Ready'},{id:2,name:'Records overview',type:'Table',status:'In progress'},{id:3,name:'Summary dashboard',type:'Dashboard',status:'Planned'}];
 let rows=seed(),nextId=4;const form=demo.querySelector('[data-demo-form]'),tbody=demo.querySelector('[data-demo-rows]'),search=demo.querySelector('.table-search'),feedback=demo.querySelector('.demo-feedback');
 const announce=message=>feedback.textContent=message;
 const cell=text=>{const td=document.createElement('td');td.textContent=text;return td};
 function render(){
  const query=search.value.trim().toLowerCase(),visible=rows.filter(r=>[r.name,r.type,r.status].join(' ').toLowerCase().includes(query));tbody.replaceChildren();
  visible.forEach(row=>{const tr=document.createElement('tr');tr.append(cell(row.name),cell(row.type));const statusTd=document.createElement('td'),select=document.createElement('select');select.className='component-status';select.setAttribute('aria-label','Status for '+row.name);['Planned','In progress','Ready'].forEach(value=>{const option=document.createElement('option');option.value=value;option.textContent=value;option.selected=value===row.status;select.append(option)});select.addEventListener('change',()=>{row.status=select.value;render();announce(row.name+' status updated to '+row.status+'.')});statusTd.append(select);tr.append(statusTd);const actionTd=document.createElement('td'),remove=document.createElement('button');remove.type='button';remove.className='remove-component';remove.textContent='Remove';remove.setAttribute('aria-label','Remove '+row.name);remove.addEventListener('click',()=>{rows=rows.filter(r=>r.id!==row.id);render();announce(row.name+' removed.');search.focus()});actionTd.append(remove);tr.append(actionTd);tbody.append(tr)});
  demo.querySelector('[data-demo-total]').textContent=rows.length;demo.querySelector('[data-demo-ready]').textContent=rows.filter(r=>r.status==='Ready').length;demo.querySelector('[data-demo-progress]').textContent=rows.filter(r=>r.status==='In progress').length;demo.querySelector('[data-demo-count]').textContent=visible.length+' of '+rows.length+' records';demo.querySelector('.demo-empty').hidden=visible.length>0;
 }
 form.addEventListener('submit',event=>{event.preventDefault();const input=form.elements.component;input.setCustomValidity('');if(!input.value.trim()){input.setCustomValidity('Enter a component name.');input.reportValidity();return}rows.push({id:nextId++,name:input.value.trim(),type:form.elements.type.value,status:form.elements.status.value});const name=input.value.trim();form.reset();search.value='';render();announce(name+' added to the sample table.');input.focus()});form.elements.component.addEventListener('input',()=>form.elements.component.setCustomValidity(''));search.addEventListener('input',render);demo.querySelector('.reset-demo').addEventListener('click',()=>{rows=seed();nextId=4;search.value='';form.reset();render();announce('Sample restored to three components.')});render();
});
document.querySelectorAll('[data-enquiry-form]').forEach(form=>form.addEventListener('submit',event=>{event.preventDefault();const name=form.elements.name.value.trim(),email=form.elements.email.value.trim(),message=form.elements.message.value.trim();if(!name||message.length<10){form.querySelector('[data-enquiry-status]').textContent='Enter your name and at least 10 characters about your project.';return}const subject='Project enquiry — '+form.dataset.topic,body='Name: '+name+'\nEmail: '+email+'\n\n'+message;form.querySelector('[data-enquiry-status]').textContent='Opening an email draft. Review and send it from your email app. If no app opens, email Shoaibahmad6342@gmail.com directly.';window.location.href='mailto:Shoaibahmad6342@gmail.com?subject='+encodeURIComponent(subject)+'&body='+encodeURIComponent(body)}));
